import{_ as t,o as a,c as i,a5 as s}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Rhythm Ledger Template","description":"Record one weekly question, minimum actions at different capacities, useful feedback, repeated resistance, and the next condition to change so a growth rhythm can be reviewed and resumed.","frontmatter":{"title":"Rhythm Ledger Template","description":"Record one weekly question, minimum actions at different capacities, useful feedback, repeated resistance, and the next condition to change so a growth rhythm can be reviewed and resumed.","updated":"2026-09-19T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/rhythm-ledger.en.md","name":"rhythm-ledger.en.md"}},"headers":[],"relativePath":"en/templates/rhythm-ledger.md","filePath":"en/templates/rhythm-ledger.md","lastUpdated":1789776000000}'),n={name:"en/templates/rhythm-ledger.md"};function r(d,e,o,h,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="rhythm-ledger-template" tabindex="-1">Rhythm Ledger Template <a class="header-anchor" href="#rhythm-ledger-template" aria-label="Permalink to &quot;Rhythm Ledger Template&quot;">​</a></h1><p>Copy this ledger into a private note and use one page each week. It is not a streak table or a dashboard for scoring your character. It helps you see what deserves to stay, which condition needs to change, and how to return after an interruption.</p><p>If the ledger has identified an obstacle, use the troubleshooting table and two examples in <a href="./../threads/practice/discipline-and-consistency">Discipline and Consistency in Practice</a>, then define one change and its acceptance criteria in a <a href="./consistency-plan">Consistency Plan</a>. That experiment card supplements this ledger. Return its conclusion to “This Week&#39;s Decision” without maintaining a separate schedule.</p><p>Do not write passwords, identity documents, customer data, medical privacy, or unauthorised third-party information. When safety, health, money, or relationship risks are involved, contact a qualified professional or a trusted support person first.</p><h2 id="_1-one-main-question" tabindex="-1">1. One Main Question <a class="header-anchor" href="#_1-one-main-question" aria-label="Permalink to &quot;1. One Main Question&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Date range:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The one question this week:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation and audience:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Baseline evidence at the start of the week:</span></span></code></pre></div><p>The question should be observable, such as “Can I explain a project risk in English without a script and answer a follow-up?” Do not write “be better this week”.</p><h2 id="_2-three-capacity-versions" tabindex="-1">2. Three Capacity Versions <a class="header-anchor" href="#_2-three-capacity-versions" aria-label="Permalink to &quot;2. Three Capacity Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capacity</th><th>When to use it</th><th>Minimum action</th><th>Evidence that must remain</th><th>Stop or downgrade condition</th></tr></thead><tbody><tr><td>Full day</td><td>Time and capacity are relatively stable</td><td></td><td></td><td></td></tr><tr><td>Compressed day</td><td>Time is short or attention is fragmented</td><td></td><td></td><td></td></tr><tr><td>Recovery day</td><td>Illness, sleeplessness, grief, or responsibility rises sharply</td><td></td><td></td><td></td></tr></tbody></table><p>The three versions serve one direction. A recovery day is not a failure. When safety, sleep, the body, or relationships are clearly affected, protect those limits before completing the plan.</p><h2 id="_3-give-repetition-an-echo" tabindex="-1">3. Give Repetition an Echo <a class="header-anchor" href="#_3-give-repetition-an-echo" aria-label="Permalink to &quot;3. Give Repetition an Echo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Action</th><th>Recall / variation / output / feedback</th><th>What new information appeared?</th><th>Which variable changes next time?</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>If four repetitions produce no new information, change the topic, listener, time limit, number of prompts, or tool permission before simply adding more repetitions.</p><h2 id="_4-record-one-useful-piece-of-feedback" tabindex="-1">4. Record One Useful Piece of Feedback <a class="header-anchor" href="#_4-record-one-useful-piece-of-feedback" aria-label="Permalink to &quot;4. Record One Useful Piece of Feedback&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who or what provided the feedback:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observation: What did the person actually see, hear, or measure?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Impact: How did it affect understanding, use, or the result?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next adjustment: Which one important variable will I change?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence location:</span></span></code></pre></div><p>When asking AI for feedback, submit your own version first. Ask for no more than three issues that affect the result, and require a distinction between observation, inference, and suggestion. A person decides what to accept.</p><h2 id="_5-interruption-and-return" tabindex="-1">5. Interruption and Return <a class="header-anchor" href="#_5-interruption-and-return" aria-label="Permalink to &quot;5. Interruption and Return&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What happened, as facts (no character judgment):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Which condition changed: time / capacity / difficulty / environment / responsibility</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The smallest return action within 24 hours:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I will explicitly not make up:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who I need to contact or which risk needs escalation:</span></span></code></pre></div><p>If the same resistance appears three times, change the time box, task size, environment, boundary, or support network. Do not repay an interruption with sleep deprivation or shame.</p><h2 id="_6-this-week-s-decision" tabindex="-1">6. This Week&#39;s Decision <a class="header-anchor" href="#_6-this-week-s-decision" aria-label="Permalink to &quot;6. This Week&#39;s Decision&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One design I will keep:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One demand or entry point I will remove:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One condition I will change next week:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One number I will stop tracking:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First action when I open the file next time:</span></span></code></pre></div><h2 id="_7-handover-and-evidence-locations" tabindex="-1">7. Handover and Evidence Locations <a class="header-anchor" href="#_7-handover-and-evidence-locations" aria-label="Permalink to &quot;7. Handover and Evidence Locations&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First version:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Revised version:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Feedback or retest:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next task: owner / date:</span></span></code></pre></div><p>Related chapters: <a href="./../threads/part-4/rhythm-and-compounding">Rhythm: Let Small Things Travel Through Time</a> | <a href="./../threads/part-4/daily-system">Daily System: Put Change into the Day</a> | <a href="./weekly-review">Weekly Review Template</a></p>`,24)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
